import json

df = pd.read_csv('${item}')
schema = json.loads('${schema_report}')

issues = []

missing = df.isnull().sum()
for col, count in missing.items():
    if count > 0:
        issues.append({'type': 'missing_values', 'column': col, 'count': int(count)})

dupes = df.duplicated().sum()
if dupes > 0:
    issues.append({'type': 'duplicates', 'count': int(dupes)})

for col_info in schema.get('columns', []):
    col_name = col_info['name']
    col_type = col_info.get('type', '')
