        numeric_vals = pd.to_numeric(df[col_name], errors='coerce')
        type_errors = numeric_vals.isna().sum() - df[col_name].isna().sum()
        if type_errors > 0:
            issues.append({'type': 'type_error', 'column': col_name, 'count': int(type_errors)})
        valid = numeric_vals.dropna()
        if len(valid) > 0:
            q1, q3 = valid.quantile(0.25), valid.quantile(0.75)
            iqr = q3 - q1
            outliers = ((valid < q1 - 1.5*iqr) | (valid > q3 + 1.5*iqr)).sum()
            if outliers > 0:
                issues.append({'type': 'outliers', 'column': col_name, 'count': int(outliers)})

