import json

df = pd.read_csv('${item}')
issues = json.loads('${issues_report}')

repairs = []

for issue in issues:
    if issue['type'] == 'missing_values':
        col = issue['column']
        if col in df.columns:
            if df[col].dtype in ['float64', 'int64']:
                df[col] = df[col].fillna(df[col].median())
                repairs.append({'action': 'fill_median', 'column': col})
            else:
                mode = df[col].mode()
                df[col] = df[col].fillna(mode.iloc[0] if not mode.empty else 'UNKNOWN')
                repairs.append({'action': 'fill_mode', 'column': col})
    elif issue['type'] == 'duplicates':
        before = len(df)
        df = df.drop_duplicates(keep='first')
        repairs.append({'action': 'drop_duplicates', 'removed': before - len(df)})
    elif issue['type'] == 'type_error':
        col = issue['column']
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
            repairs.append({'action': 'coerce_numeric', 'column': col})
    elif issue['type'] == 'outliers':
        col = issue['column']
        if col in df.columns:
            q1, q3 = df[col].quantile(0.25), df[col].quantile(0.75)
            iqr = q3 - q1
            df[col] = df[col].clip(q1 - 1.5*iqr, q3 + 1.5*iqr)
            repairs.append({'action': 'clip_outliers', 'column': col})

result = {'repairs_log': json.dumps(repairs), 'repaired_df': df.to_json()}
